package com.dynasty.armorqa;
import static com.dynasty.armorqa.ArmorNetworkQa.*;
import com.dynasty.expansion.EquipmentBehaviors;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.inventory.InventoryScreen;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.Vec3;
import net.minecraft.sounds.SoundSource;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.*;
import net.minecraftforge.registries.ForgeRegistries;
import java.nio.file.Files;
import java.util.*;
/** Targeted native movement/sound and repeated same-stack C2S armor QA only. */
public class GapQa {
 static boolean begun,finished;static int seq,stage,ticks,setIndex=-1,cycle;static String action="",setName="leather";static long commandTick;static int clientSeq=-1,clientTicks,clicks;static final List<Map<String,Object>> trace=new ArrayList<>(),sounds=new ArrayList<>(),matrix=new ArrayList<>();static Map<String,Object> firstEquipped,baseline;static Vec3 segmentStart;static double traveled;static int equipmentChanges;static final String[] SUFFIX={"helmet","chestplate","leggings","boots"};
 static boolean enabled(){return "gap".equals(System.getProperty("dynasty.armorqa.suite"));}
 static Map<String,Object> attrs(LivingEntity p){var out=new TreeMap<String,Object>();for(var a:List.of(Attributes.ATTACK_DAMAGE,Attributes.ARMOR,Attributes.ARMOR_TOUGHNESS,Attributes.MAX_HEALTH,Attributes.MOVEMENT_SPEED,Attributes.KNOCKBACK_RESISTANCE,Attributes.LUCK,net.minecraftforge.common.ForgeMod.SWIM_SPEED.get())){var i=p.getAttribute(a);if(i!=null)out.put(ForgeRegistries.ATTRIBUTES.getKey(a).toString(),obj("value",i.getValue(),"modifiers",i.getModifiers().stream().sorted(Comparator.comparing(m->m.getId().toString())).map(m->obj("uuid",m.getId().toString(),"name",m.getName(),"amount",m.getAmount(),"operation",m.getOperation().toString())).toList()));}return out;}
 static void supply(ServerPlayer p,String s){p.getInventory().clearContent();p.removeAllEffects();for(var k:List.copyOf(p.getPersistentData().getAllKeys()))if(k.startsWith("cod4"))p.getPersistentData().remove(k);for(int i=0;i<4;i++){var stack=item(s+"_"+SUFFIX[i]);stack.getOrCreateTag().putString("gapIdentity",s+"/"+i);p.getInventory().setItem(9+i,stack);}p.getFoodData().setFoodLevel(20);p.getFoodData().setExhaustion(0);p.teleportTo(server.overworld(),.5,-60,.5,90,0);p.getInventory().setChanged();p.inventoryMenu.broadcastChanges();}
 static void command(String a)throws Exception{action=a;seq++;ticks=0;commandTick=server.overworld().getGameTime();write("gap-command.json",obj("seq",seq,"action",a,"set",setName,"cycle",cycle,"stage",stage,"peer",players(server).get(1).getUUID().toString()));}
 public static void client(Minecraft m)throws Exception{if(HOST&&!begun&&server.getPlayerList().getPlayerCount()==2&&has("peer-world-ready")){begun=true;work=server.submit(()->{try{var ps=players(server);require(ps.get(1).connection.connection.getRemoteAddress() instanceof java.net.InetSocketAddress,"actual TCP peer");write("connections.json",ps.stream().map(p->obj("name",p.getGameProfile().getName(),"uuid",p.getUUID().toString(),"remote",p.connection.connection.getRemoteAddress().toString())).toList());reset(ps.get(0));reset(ps.get(1));ps.get(0).teleportTo(server.overworld(),.5,-60,45.5,180,0);supply(ps.get(1),"leather");stage=0;command("equip");}catch(Exception x){throw new RuntimeException(x);}});return;}if(!has("gap-command.json"))return;var c=JsonParser.parseString(Files.readString(OUT.resolve("gap-command.json"))).getAsJsonObject();int n=c.get("seq").getAsInt();String a=c.get("action").getAsString();if(n!=clientSeq){clientSeq=n;clientTicks=0;clicks=0;m.options.keyUp.setDown(false);m.options.keyShift.setDown(false);m.options.keySprint.setDown(false);if(!HOST&&(a.equals("equip")||a.equals("unwear")))m.setScreen(new InventoryScreen(m.player));}clientTicks++;if(!HOST){if(a.equals("equip")||a.equals("unwear")){if(clientTicks%3==0&&clicks<4){if(a.equals("equip")){String expected="dynasty:"+c.get("set").getAsString()+"_"+SUFFIX[clicks];int slot=-1;for(int k=9;k<36;k++)if(ForgeRegistries.ITEMS.getKey(m.player.getInventory().getItem(k).getItem()).toString().equals(expected))slot=k;if(slot<0)return;m.gameMode.handleInventoryMouseClick(m.player.inventoryMenu.containerId,slot,0,ClickType.QUICK_MOVE,m.player);}else m.gameMode.handleInventoryMouseClick(m.player.inventoryMenu.containerId,5+clicks,0,ClickType.QUICK_MOVE,m.player);clicks++;}if(clicks==4&&clientTicks>=25){m.setScreen(null);if(!has("peer-gap-input-"+n))mark("peer-gap-input-"+n);}}else if(a.equals("sprint")||a.equals("crouch")){m.setScreen(null);m.player.setYRot(90);m.player.setXRot(0);m.options.keyUp.setDown(true);m.options.keySprint.setDown(!a.equals("crouch"));m.options.keyShift.setDown(a.equals("crouch"));if(!a.equals("crouch"))m.player.setSprinting(true);if(clientTicks==3)mark("peer-gap-input-"+n);}else{if(clientTicks==3)mark("peer-gap-input-"+n);}}
 if(clientTicks>=40&&draw&&!has(ROLE+"-gap-frame-"+n)){write(ROLE+"-gap-frame-"+n+".json",obj("captureEvent","AFTER_LEVEL real rendered world frame","command",c,"own",snap(m.player),"attrs",attrs(m.player),"players",m.level.players().stream().map(ArmorNetworkQa::snap).toList(),"masterVolume",m.options.getSoundSourceVolume(SoundSource.MASTER),"playersVolume",m.options.getSoundSourceVolume(SoundSource.PLAYERS)));try(var im=net.minecraft.client.Screenshot.takeScreenshot(m.getMainRenderTarget())){if(a.equals("crouch")||n==2)im.writeToFile(OUT.resolve(ROLE+"-gap-frame-"+n+".png"));}mark(ROLE+"-gap-frame-"+n);}
 }
 @SubscribeEvent public static void server(TickEvent.ServerTickEvent e){if(!enabled()||!HOST||!begun||finished||e.phase!=TickEvent.Phase.END)return;try{ticks++;var p=players(server).get(1);if(stage>=1&&stage<=3){if(segmentStart!=null){double d=p.position().distanceTo(segmentStart);if(d<2)traveled+=d;}segmentStart=p.position();trace.add(obj("seq",seq,"action",action,"tick",server.overworld().getGameTime(),"age",ticks,"shift",p.isShiftKeyDown(),"sprint",p.isSprinting(),"onGround",p.onGround(),"position",List.of(p.getX(),p.getY(),p.getZ()),"distance",traveled));if(ticks<180)return;}else if(ticks<55)return;
 if(!has("peer-gap-input-"+seq)||!has("host-gap-frame-"+seq)||!has("peer-gap-frame-"+seq))return;
 if(stage==0){require(EquipmentBehaviors.pieces(p,"leather")==4,"actual C2S leather equip");stage=1;segmentStart=null;traveled=0;command("sprint");return;}
 if(stage>=1&&stage<=3){write("gap-sound-server-segment-"+stage+".json",obj("stage",stage,"seq",seq,"action",action,"traveled",traveled,"trace",trace.stream().filter(x->x.get("seq").equals(seq)).toList()));if(stage<3){stage++;p.teleportTo(server.overworld(),.5,-60,.5,90,0);segmentStart=null;traveled=0;command(stage==2?"crouch":"sprint");return;}stage=4;command("unwear");return;}
 if(stage==4){require(EquipmentBehaviors.pieces(p,setName)==0,"sound test native unwear");setIndex=0;cycle=0;setName=SETS.get(setIndex);supply(p,setName);stage=5;command("settle");return;}
 if(stage==5){baseline=attrs(p);stage=6;command("equip");return;}
 if(stage==6){require(EquipmentBehaviors.pieces(p,setName)==4,"native full threshold");var now=attrs(p);if(cycle==0)firstEquipped=now;boolean same=now.equals(firstEquipped);var gear=new ArrayList<String>();for(var sl:EquipmentSlot.values())if(sl.getType()==EquipmentSlot.Type.ARMOR)gear.add(p.getItemBySlot(sl).getOrCreateTag().getString("gapIdentity"));boolean identities=gear.size()==4&&gear.stream().allMatch(x->x.startsWith(setName+"/"));matrix.add(obj("set",setName,"cycle",cycle+1,"action","equipped","sameUuidModifiersAsFirst",same,"sameSuppliedStackIdentity",identities,"attributes",now,"gearIdentities",gear,"nativeEquipmentChanges",equipmentChanges,"tick",server.overworld().getGameTime()));stage=7;command("unwear");return;}
 if(stage==7){require(EquipmentBehaviors.pieces(p,setName)==0,"native repeated unwear");var now=attrs(p);matrix.add(obj("set",setName,"cycle",cycle+1,"action","unworn","returnedToBaseline",now.equals(baseline),"attributes",now,"nativeEquipmentChanges",equipmentChanges,"tick",server.overworld().getGameTime()));cycle++;if(cycle<3){stage=6;command("equip");return;}setIndex++;write("gap-repeat-progress.json",matrix);if(setIndex<SETS.size()){cycle=0;setName=SETS.get(setIndex);supply(p,setName);stage=5;command("settle");return;}finished=true;write("gap-repeat-result.json",obj("sets",28,"cyclesPerSet",3,"observations",matrix,"passed",matrix.stream().allMatch(x->!Boolean.FALSE.equals(x.get("sameUuidModifiersAsFirst"))&&!Boolean.FALSE.equals(x.get("sameSuppliedStackIdentity"))&&!Boolean.FALSE.equals(x.get("returnedToBaseline")))));write("gap-sound-server-trace.json",trace);mark("server-PASS");mark("server-COMPLETE");}
 }catch(Throwable x){try{write("gap-error.json",obj("error",x.toString(),"stage",stage,"seq",seq));mark("server-COMPLETE");}catch(Exception ignored){}x.printStackTrace();}}
 @SubscribeEvent public static void gear(net.minecraftforge.event.entity.living.LivingEquipmentChangeEvent e){if(enabled()&&e.getEntity() instanceof ServerPlayer p&&p.getGameProfile().getName().endsWith("Peer")&&e.getSlot().getType()==EquipmentSlot.Type.ARMOR)equipmentChanges++;}
 static void captureSound(String kind,String id,Object detail){if(!enabled()||clientSeq<0||!id.endsWith(".step"))return;try{var m=Minecraft.getInstance();sounds.add(obj("kind",kind,"sound",id,"seq",clientSeq,"clientTicks",clientTicks,"shift",m.player!=null&&m.player.isShiftKeyDown(),"sprint",m.player!=null&&m.player.isSprinting(),"onGround",m.player!=null&&m.player.onGround(),"detail",detail));write(ROLE+"-gap-sounds.json",sounds);}catch(Exception x){throw new RuntimeException(x);}}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void play(net.minecraftforge.client.event.sound.PlaySoundEvent e){if(!enabled()||clientSeq<0||!e.getName().endsWith(".step"))return;captureSound("native-SoundEngine-PlaySoundEvent",e.getName(),obj("actualSound",e.getSound()!=null,"position",List.of(e.getOriginalSound().getX(),e.getOriginalSound().getY(),e.getOriginalSound().getZ())));}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void source(net.minecraftforge.client.event.sound.PlaySoundSourceEvent e){captureSound("native-PlaySoundSourceEvent-channel",e.getSound().getLocation().getPath(),"Actual native sound source after SoundEngine checks");}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true) public static void position(net.minecraftforge.event.PlayLevelSoundEvent.AtPosition e){if(!enabled()||e.getSound()==null)return;if(e.getLevel().isClientSide())captureSound("native-AtPosition",e.getSound().value().getLocation().getPath(),obj("canceled",e.isCanceled(),"volume",e.getNewVolume()));}
}
